  var dict = {
    fa: fa,
    en: en
  };
  var current = "fa";
  function detect() {
    try {
      var v = localStorage.getItem("oc-locale");
      if (v === "fa" || v === "en") current = v;
    } catch (e) {}
  }
  function setLocale(l) {
    current = l;
    try {
      localStorage.setItem("oc-locale", l);
    } catch (e) {}
    document.documentElement.lang = l;
    document.documentElement.dir = l === "fa" ? "rtl" : "ltr";
  }
  function t(key) {
    return dict[current][key] || dict.fa[key] || key;
  }
  function locale() {
    return current;
  }
  function isRTL() {
    return current === "fa";
  }
  window.OC = window.OC || {};
  window.OC.i18n = {
    t: t,
    setLocale: setLocale,
    locale: locale,
    isRTL: isRTL,
    detect: detect
  };
